import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, mkdtempSync, rmSync, readdirSync, mkdirSync, cpSync } from 'node:fs';
import { execFileSync, spawnSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import path from 'node:path';
import canonicalize from 'canonicalize';
import { createHash } from 'node:crypto';
import { previewSnapshot } from '../lib/manager/decisions.mjs';
import { SNAPSHOT_LIMITS } from '../lib/manager/snapshot.mjs';
const fixtures=JSON.parse(readFileSync(new URL('./fixtures/manager-candidates.json',import.meta.url))).cases;
const fresh=id=>structuredClone(fixtures.find(c=>c.id===id));
const run=c=>previewSnapshot(JSON.stringify(c.config),JSON.stringify(c.snapshot),c.options);
const codes=r=>r.streams.flatMap(s=>s.reasons.map(r=>r.code));
const selected=r=>r.streams.filter(s=>s.decision==='select').map(s=>s.selected_ticket_id);
for(const fixture of fixtures)test(`frozen scenario ${fixture.id}`,()=>{const before=JSON.stringify(fixture),r=run(fixture);assert.equal(r.valid,true,JSON.stringify(r));assert.equal(r.streams.length,fixture.expected.streams.length);assert.deepEqual(selected(r),fixture.expected.streams.filter(e=>e.decision==='select').map(e=>e.selected_ticket_id));for(const e of fixture.expected.streams){const s=r.streams.find(s=>s.scope.project_id===e.project_id&&s.scope.label===e.label);assert.ok(s);assert.equal(s.decision,e.decision);assert.equal(s.selected_ticket_id,e.selected_ticket_id);assert.equal(s.return_count,e.return_count);if(e.reason)assert.ok(s.reasons.some(r=>r.code===e.reason),JSON.stringify(s));if(fixture.id.startsWith('membership-')){assert.deepEqual(s.scope,{site:fixture.snapshot.site,project_id:e.project_id,label:e.label});for(const field of ['occupied_ids','blocked_ids','human_review_ids','counts_complete'])if(Object.hasOwn(e,field))assert.deepEqual(s[field],e[field],fixture.id+' '+field);for(const code of e.reasons??[])assert.ok(s.reasons.some(r=>r.code===code),fixture.id+' '+code);for(const code of e.absent_reasons??[])assert.ok(!s.reasons.some(r=>r.code===code),fixture.id+' '+code);if(e.mismatch_path)assert.ok(s.reasons.some(r=>r.code==='MEMBERSHIP_MISMATCH'&&r.path===e.mismatch_path),fixture.id);} }assert.equal(JSON.stringify(fixture),before);assert.deepEqual(run(fixture),r);assert.equal(r.writes,0);assert.equal(r.execution_authorized,false);});
test('exact expected digest covers configuration and every snapshot field',()=>{const c=fresh('S01'),r=run(c);assert.equal(r.snapshot_digest,'sha256:'+createHash('sha256').update(canonicalize({configuration_digest:r.configuration_digest,snapshot:c.snapshot})).digest('hex'));c.options={expectedSnapshotDigest:r.snapshot_digest};assert.equal(run(c).status,'complete');for(const mutate of [c=>c.config.projects[0].key='RENAMED',c=>c.snapshot.issues[1].body+=' ',c=>c.snapshot.retained_complete=false]){const next=structuredClone(c);mutate(next);assert.deepEqual(selected(run(next)),[]);assert.ok(codes(run(next)).includes('CHANGED_INPUT'));}});
test('shared completeness and local incompleteness never become zero inventory',()=>{for(const field of ['discovery_complete','retained_complete']){const c=fresh('S18');c.snapshot[field]=false;const r=run(c);assert.deepEqual(selected(r),[]);assert.ok(r.streams.every(s=>s.return_count===null));}const c=fresh('S18');c.snapshot.stream_checks[1].known_ids_complete=false;const r=run(c);assert.deepEqual(selected(r),['1001']);assert.equal(r.status,'partial');assert.equal(r.streams[1].return_count,null);});
test('three occupied native stages count malformed bodies; pending intents and unknown stages hold',()=>{for(const status of ['2','3','4']){const c=fresh('S11');c.snapshot.issues[2].status_id=status;c.snapshot.issues[2].body='broken';const r=run(c);assert.deepEqual(selected(r),[]);assert.deepEqual(r.streams[0].occupied_ids,['1002']);}const c=fresh('S01');c.snapshot.pending_intents=[{project_id:'100',label:'stream-1',ticket_id:'1001',attempt_id:'attempt'}];assert.ok(codes(run(c)).includes('PENDING_INTENT'));});
test('exact bound current completion alone accounts for repairs on every member',()=>{
 for(const id of ['repair-prerequisite-complete','repair-independent-complete','stack-independent-complete']){const c=fresh(id);assert.deepEqual(selected(run(c)),['1100']);
  for(const mutate of [c=>c.snapshot.completion_receipts=[],c=>c.snapshot.issues.at(-1).body+=' ',c=>c.snapshot.issues.at(-1).pointer.assignment.digest='sha256:'+'f'.repeat(64),c=>{const e=JSON.parse(c.snapshot.completion_receipts[0]);e.consumer='worker';c.snapshot.completion_receipts[0]=JSON.stringify(e);},c=>{const e=JSON.parse(c.snapshot.completion_receipts[0]);e.comment_pages[0].is_last=false;c.snapshot.completion_receipts[0]=JSON.stringify(e);},c=>c.snapshot.stream_checks[0].repair_inventory_complete=false,c=>c.snapshot.issues.at(-1).status_id='6']){const n=structuredClone(c);mutate(n);assert.deepEqual(selected(run(n)),[],id);}
 }
 const c=fresh('repair-independent-complete'),i=c.snapshot.issues.at(-1);c.snapshot.required_repairs=[{project_id:'100',label:'stream-1',ticket_id:i.id,reason:'required_request',references:structuredClone(i.required_requests)}];assert.deepEqual(selected(run(c)),['1100']);const n=structuredClone(c);n.snapshot.required_repairs[0].references[0].digest='sha256:'+'f'.repeat(64);assert.deepEqual(selected(run(n)),[]);assert.ok(codes(run(n)).includes('REPAIR_POLICY_PENDING'));
 // A consistent newly declared but nonexistent obligation still fails the canonical chain.
 const extra=structuredClone(i.required_requests[0]);extra.record_id='00000000-0000-4000-8000-999999999999';i.required_requests.push(extra);const e=JSON.parse(c.snapshot.completion_receipts[0]);e.issues.find(x=>x.id===i.id).required_requests.push(extra);c.snapshot.completion_receipts[0]=JSON.stringify(e);assert.deepEqual(selected(run(c)),[]);
});
test('Human Review and accepted-later completion use exact native stage and all current requirements',()=>{for(const st of ['5','8']){const c=fresh('S06'),i=c.snapshot.issues.at(-1),e=JSON.parse(c.snapshot.completion_receipts[0]);i.status_id=st;e.issues[0].stage_id=st;c.snapshot.completion_receipts[0]=JSON.stringify(e);assert.deepEqual(selected(run(c)),['1100']);}for(const mutate of [c=>c.snapshot.issues.at(-1).status_id='10',c=>{const e=JSON.parse(c.snapshot.completion_receipts[0]);e.trusted.projects[0].actors.qa=['different'];c.snapshot.completion_receipts[0]=JSON.stringify(e);},c=>{const e=JSON.parse(c.snapshot.completion_receipts[0]);e.requirements[0].context_body+=' ';c.snapshot.completion_receipts[0]=JSON.stringify(e);}]){const c=fresh('S06');mutate(c);assert.deepEqual(selected(run(c)),[]);}});
test('structural and bounds failures produce no partial selections or raw diagnostics',()=>{const c=fresh('S01');for(const mutate of [c=>c.snapshot.issues.push(c.snapshot.issues[1]),c=>c.snapshot.projects.push(c.snapshot.projects[0]),c=>c.snapshot.issues[1]['SECRET-/key']='SECRET-BODY',c=>c.snapshot.stream_checks.push(c.snapshot.stream_checks[0]),c=>c.snapshot.schema='v2',c=>c.snapshot.issues[1].labels=Array(101).fill('x'),c=>c.snapshot.site='https://u:SECRET@jira.example.invalid']){const n=structuredClone(c);mutate(n);const r=run(n);assert.equal(r.valid,false);assert.deepEqual(r.streams,[]);assert.ok(!JSON.stringify(r).includes('SECRET'));}
 for(const raw of ['{"schema":"x","schema":"y"}','a: 1','{"x":9007199254740992}',new Uint8Array([0xc3,0x28]),'{"x":"\\ud800"}','{"a":'+JSON.stringify(Array(1001).fill(0))+'}'])assert.equal(previewSnapshot(JSON.stringify(c.config),raw).valid,false);
 const raw=JSON.stringify(c.snapshot),at=raw+' '.repeat(SNAPSHOT_LIMITS.bytes-Buffer.byteLength(raw));assert.equal(previewSnapshot(JSON.stringify(c.config),at).valid,true);assert.equal(previewSnapshot(JSON.stringify(c.config),at+' ').scope_diagnostics[0].code,'LIMIT');
 const many=structuredClone(c);many.config.projects=Array.from({length:101},(_,i)=>({...structuredClone(c.config.projects[0]),id:String(i)}));assert.equal(run(many).scope_diagnostics[0].code,'LIMIT');
});
test('raw finite floating literals retain canonical work parser provenance in YAML and ADF',()=>{for(const format of ['yaml','adf']){const c=fresh('S01'),i=c.snapshot.issues[1];const w=JSON.parse(i.body),ctx=JSON.parse(i.context_body);/* human-only contract has no arbitrary numeric slots; use allowed database parameter in mixed canonical fixture. */const mixed=JSON.parse(readFileSync(new URL('./fixtures/work-semantics.json',import.meta.url))).mixed;mixed.context.subject_key=i.key;mixed.context.prerequisite_graph=[{ticket:i.key,prerequisites:[]}];mixed.work.testing_strategy.cases[0].steps[2].database.parameters[0]=1e20;mixed.context.operations[2].contract.database.parameters[0]=1e20;const body=JSON.stringify(mixed.work).replaceAll('100000000000000000000','1e20');i.format=format;i.body=format==='yaml'?body:JSON.stringify({version:1,type:'doc',content:[{type:'codeBlock',attrs:{language:'yaml'},content:[{type:'text',text:body}]}]});i.context_body=JSON.stringify(mixed.context).replaceAll('100000000000000000000','1e20');assert.deepEqual(selected(run(c)),['1001']);}});
test('CLI is strict, finite, nonwriting and equivalent to the pure API',()=>{const temp=mkdtempSync(path.join(tmpdir(),'pgb-preview-')),cli=new URL('../scripts/manager-preview.mjs',import.meta.url);try{const c=fresh('S01'),config=path.join(temp,'config.json'),input=path.join(temp,'snapshot.json');writeFileSync(config,JSON.stringify(c.config));writeFileSync(input,JSON.stringify(c.snapshot));const before=readdirSync(temp).map(p=>[p,readFileSync(path.join(temp,p),'utf8')]);const args=[cli.pathname,'--config',config,'--input',input];assert.deepEqual(JSON.parse(execFileSync(process.execPath,[...args,'--json'],{cwd:temp,encoding:'utf8'})),run(c));const human=execFileSync(process.execPath,args,{cwd:temp,encoding:'utf8'});assert.match(human,/Local supplied snapshot only/);assert.match(human,/selected EX-2/);assert.deepEqual(readdirSync(temp).map(p=>[p,readFileSync(path.join(temp,p),'utf8')]),before);
 for(const extra of [['--input',input],['--unknown'],['stray'],['--expected-snapshot-digest','bad']]){const r=spawnSync(process.execPath,[...args,...extra,'--json'],{encoding:'utf8'});assert.equal(r.status,2);assert.equal(JSON.parse(r.stdout).scope_diagnostics[0].code,'USAGE');}
 for(const file of [temp,path.join(temp,'missing')])assert.equal(spawnSync(process.execPath,[cli.pathname,'--config',config,'--input',file,'--json'],{encoding:'utf8'}).status,2);
 execFileSync('mkfifo',[path.join(temp,'fifo')]);assert.equal(spawnSync(process.execPath,[cli.pathname,'--config',config,'--input',path.join(temp,'fifo'),'--json'],{encoding:'utf8',timeout:2000}).status,2);
 const isolated=path.join(temp,'isolated');mkdirSync(isolated);cpSync(cli,path.join(isolated,'preview.mjs'));assert.equal(spawnSync(process.execPath,[path.join(isolated,'preview.mjs'),'--help','--json'],{encoding:'utf8'}).status,0);const missing=spawnSync(process.execPath,[path.join(isolated,'preview.mjs'),'--config',config,'--input',input,'--json'],{encoding:'utf8'});assert.equal(missing.status,2);assert.equal(JSON.parse(missing.stdout).scope_diagnostics[0].code,'SETUP');
 }finally{rmSync(temp,{recursive:true,force:true});}});

test('counts depend on known native facts, independently of repair-inventory and ownership holds',()=>{for(const id of ['S30','S31','S32'])assert.ok(run(fresh(id)).streams.every(s=>s.counts_complete&&s.return_count===1));const c=fresh('S12');c.snapshot.stream_checks[0].repair_inventory_complete=false;const r=run(c);assert.equal(r.streams[0].decision,'hold');assert.equal(r.streams[0].return_count,5);c.snapshot.stream_checks[0].known_ids_complete=false;assert.equal(run(c).streams[0].return_count,null);});
test('known lost-label active child cannot vanish without a retained row; independent removals respect incoming obligations',()=>{const c=fresh('S01'),child=structuredClone(c.snapshot.issues[1]);child.id='1002';child.key='EX-3';child.labels=[];child.status_id='2';child.body=null;child.context_body=null;c.snapshot.issues.push(child);assert.deepEqual(selected(run(c)),[]);assert.ok(codes(run(c)).includes('MEMBERSHIP_MISMATCH'));const incoming=fresh('S05'),ep=JSON.parse(incoming.snapshot.issues[0].body);ep.workstreams[0].story_order=['EX-2'];incoming.snapshot.issues[0].body=JSON.stringify(ep);assert.deepEqual(selected(run(incoming)),[]);assert.ok(codes(run(incoming)).includes('MEMBERSHIP_MISMATCH'));});
test('malicious YAML work, stale context graph and site/project/identity substitutions never establish readiness',()=>{for(const body of ['x: &a 1\ny: *a','x: !unsafe secret','x: 1\nx: 2','---\nx: 1\n---\ny: 2','%YAML 1.1\n---\nx: 1']){const c=fresh('S01');c.snapshot.issues[1].body=body;assert.deepEqual(selected(run(c)),[]);assert.ok(codes(run(c)).includes('INVALID_WORK'));}for(const mutate of [c=>{const x=JSON.parse(c.snapshot.issues[1].context_body);x.subject_key='WRONG';c.snapshot.issues[1].context_body=JSON.stringify(x);},c=>{const x=JSON.parse(c.snapshot.issues[1].context_body);x.repositories[0].url='https://untrusted.example.invalid';c.snapshot.issues[1].context_body=JSON.stringify(x);},c=>{const x=JSON.parse(c.snapshot.issues[1].context_body);x.prerequisite_graph[0].prerequisites=['MISSING'];c.snapshot.issues[1].context_body=JSON.stringify(x);}]){const c=fresh('S01');mutate(c);assert.deepEqual(selected(run(c)),[]);}});
test('native full numbered suffix, opt-in pause and per-project maps preserve exact identity',()=>{const c=fresh('S18');const second=c.snapshot.issues.filter(i=>i.id==='901'||i.id==='1002');for(const i of second){i.labels=i.labels.map(l=>l==='stream-2'?'stream-11':l);if(i.type_id==='21'){const w=JSON.parse(i.body);w.workstreams[0].label='stream-11';i.body=JSON.stringify(w);}}c.snapshot.stream_checks[1].label='stream-11';assert.deepEqual(selected(run(c)),['1001']);assert.equal(run(c).streams[1].scope.label,'stream-11');const two=fresh('H03-A-full');two.config.projects[1].inherit=two.config.projects[1].inherit.filter(s=>s!=='stages');two.config.projects[1].mappings.stages=structuredClone(two.config.defaults.stages);two.config.projects[1].mappings.stages['Ready to Work']='2';two.config.projects[1].mappings.stages['In Progress']='1';const ep=two.snapshot.issues.find(i=>i.project_id==='200'&&i.type_id==='21');ep.status_id='1';const t=two.snapshot.issues.find(i=>i.project_id==='200'&&i.type_id==='22');t.status_id='2';assert.deepEqual(selected(run(two)),['11001']);});
test('no other targeted proof or incomplete/partial result waives member obligations',()=>{for(const mutate of [c=>{const e=JSON.parse(c.snapshot.completion_receipts[0]);e.target.ticket_id='1001';c.snapshot.completion_receipts[0]=JSON.stringify(e);},c=>{const e=JSON.parse(c.snapshot.completion_receipts[0]);e.trusted.manager_assignments[0].assignment.digest='sha256:'+'f'.repeat(64);c.snapshot.completion_receipts[0]=JSON.stringify(e);},c=>{const e=JSON.parse(c.snapshot.completion_receipts[0]);e.pr_receipts[0].source_revision='f'.repeat(40);c.snapshot.completion_receipts[0]=JSON.stringify(e);},c=>{const e=JSON.parse(c.snapshot.completion_receipts[0]);e.comment_pages[0].comments[0].updated='2030-01-01T00:00:00Z';c.snapshot.completion_receipts[0]=JSON.stringify(e);},c=>c.snapshot.completion_receipts.push(c.snapshot.completion_receipts[0])]){const c=fresh('repair-independent-complete');mutate(c);assert.deepEqual(selected(run(c)),[]);}const c=fresh('stack-independent-complete');const target=c.snapshot.issues.find(i=>i.id==='1001');const unrelated=c.snapshot.issues.find(i=>i.id==='1000');unrelated.required_requests=structuredClone(target.required_requests);assert.deepEqual(selected(run(c)),[]);});
test('finite issue/Epic/project/embedded-work/depth/list boundaries reject one-over without sampling',()=>{const c=fresh('S01');const native=c.snapshot.issues[1];for(let n=0;n<998;n++){const i=structuredClone(native);i.id=String(3000+n);i.key='N-'+n;i.status_id='9';i.body=null;i.context_body=null;c.snapshot.issues.push(i);}assert.equal(c.snapshot.issues.length,1000);assert.equal(run(c).valid,true);c.snapshot.issues.push({...native,id:'9999',key:'OVER'});assert.equal(run(c).scope_diagnostics[0].code,'LIMIT');const epics=fresh('S01');for(let n=0;n<99;n++)epics.snapshot.issues.push({...structuredClone(epics.snapshot.issues[0]),id:String(3000+n),key:'E-'+n,body:null,context_body:null,labels:[]});assert.equal(run(epics).valid,true);epics.snapshot.issues.push({...epics.snapshot.issues[0],id:'9999',key:'OVER'});assert.equal(run(epics).scope_diagnostics[0].code,'LIMIT');const projects=fresh('S01');projects.config.projects=Array.from({length:100},(_,i)=>({...structuredClone(projects.config.projects[0]),id:String(100+i)}));projects.snapshot.projects=projects.config.projects.map(p=>({project_id:p.id,complete:true}));assert.equal(run(projects).valid,true);projects.config.projects.push({...projects.config.projects[0],id:'200'});projects.snapshot.projects.push({project_id:'200',complete:true});assert.equal(run(projects).scope_diagnostics[0].code,'LIMIT');for(const field of ['body','context_body']){const n=fresh('S01');n.snapshot.issues[1][field]=' '.repeat(65537);assert.equal(run(n).scope_diagnostics[0].code,'LIMIT');}const raw=JSON.stringify({x:Array.from({length:49}).reduce(v=>[v],'x')});assert.equal(previewSnapshot(JSON.stringify(fresh('S01').config),raw).scope_diagnostics[0].code,'LIMIT');});

test('pure invocation cannot call provider, network, process or filesystem mutation APIs',()=>{const temp=mkdtempSync(path.join(tmpdir(),'pgb-pure-audit-'));try{const specs=obligationCases(fixtures),c=[fresh('S01'),...specs.map(s=>s.c)],inputs=path.join(temp,'fixture.json');writeFileSync(inputs,JSON.stringify(c));const script=`import fs from 'node:fs';import fsp from 'node:fs/promises';import cp from 'node:child_process';import http from 'node:http';import https from 'node:https';import net from 'node:net';import {syncBuiltinESMExports} from 'node:module';const raw=JSON.parse(fs.readFileSync(process.argv[1]));let attemptedEffects=0;const stop=()=>{attemptedEffects++;throw Error('SIDE_EFFECT_ATTEMPT')};for(const k of ['writeFileSync','appendFileSync','renameSync','unlinkSync','mkdirSync','rmSync','createWriteStream'])fs[k]=stop;for(const k of ['writeFile','appendFile','rename','unlink','mkdir','rm'])fsp[k]=stop;for(const k of ['exec','execSync','execFile','execFileSync','spawn','spawnSync','fork'])cp[k]=stop;http.request=stop;http.get=stop;https.request=stop;https.get=stop;net.connect=stop;net.createConnection=stop;globalThis.fetch=stop;syncBuiltinESMExports();const {previewSnapshot}=await import(${JSON.stringify(new URL('../lib/manager/decisions.mjs',import.meta.url).href)});const r=raw.map(c=>previewSnapshot(JSON.stringify(c.config),JSON.stringify(c.snapshot)));if(attemptedEffects!==0||r[0].streams[0]?.selected_ticket_id!=='1001')throw Error('SIDE_EFFECT_OR_CONTROL_FAILURE');console.log(JSON.stringify(r));`;const result=JSON.parse(execFileSync(process.execPath,['--input-type=module','-e',script,inputs],{encoding:'utf8'}));assert.equal(result[0].writes,0);assert.equal(result.length,14);for(const [index,spec]of specs.entries())assertObligationResult(result[index+1],spec);assert.deepEqual(readdirSync(temp),['fixture.json']);assert.equal(readFileSync(inputs,'utf8'),JSON.stringify(c));}finally{rmSync(temp,{recursive:true,force:true});}});

test('malformed scheduling fields on an independent Ready candidate are skipped without hiding valid work',()=>{for(const prerequisites of [{ticket:'fake'},'fake',42,[null],['fake']]){const c=fresh('S04'),i=c.snapshot.issues[2],body=JSON.parse(c.snapshot.issues[1].body);body.prerequisites=prerequisites;i.body=JSON.stringify(body);assert.deepEqual(selected(run(c)),['1001']);}const c=fresh('S04'),i=c.snapshot.issues[2];i.body=c.snapshot.issues[1].body;i.context_body='{"prerequisite_graph":42}';assert.deepEqual(selected(run(c)),['1001']);});

test('candidate errors identify declared fields while dropping secret unknown key paths',()=>{const c=fresh('S04'),i=c.snapshot.issues[2],body=JSON.parse(c.snapshot.issues[1].body);body.acceptance_criteria=null;body['secret-token-123']='credential-value';i.body=JSON.stringify(body);const r=run(c),candidate=r.streams[0].candidates.find(x=>x.ticket_id==='1002');assert.deepEqual(selected(r),['1001']);assert.ok(candidate.reasons.some(r=>r.path==='/issues/2/body/acceptance_criteria'));assert.ok(!JSON.stringify(r).includes('secret-token'));assert.ok(!JSON.stringify(r).includes('credential-value'));});

