test('distinct bounded object references reach repair policy; canonical duplicates still reject in either list',()=>{
 const refs=[{ticket_id:'1001',comment_id:'9001',record_id:'40000000-0000-4000-8000-000000000001',digest:'sha256:'+'1'.repeat(64)},{ticket_id:'1001',comment_id:'9002',record_id:'40000000-0000-4000-8000-000000000002',digest:'sha256:'+'2'.repeat(64)}];
 for(const side of [false,true]){const c=fresh('S01');c.snapshot.issues[1].required_requests=structuredClone(refs);if(side)c.snapshot.required_repairs=[{project_id:'100',label:'stream-1',ticket_id:'1001',reason:'required_request',references:structuredClone(refs)}];const r=run(c);assert.equal(r.valid,true);assert.equal(r.status,'complete');assert.deepEqual(selected(r),[]);assert.ok(codes(r).includes('REPAIR_POLICY_PENDING'));const duplicate=structuredClone(c),target=side?duplicate.snapshot.required_repairs[0].references:duplicate.snapshot.issues[1].required_requests;target.push(Object.fromEntries(Object.entries(target[0]).reverse()));const d=run(duplicate);assert.equal(d.valid,false);assert.equal(d.scope_diagnostics[0].code,'STRUCTURE');assert.deepEqual(d.streams,[]);}
});

