 const extra={ticket_id:'1000',comment_id:'9998',record_id:'40000000-0000-4000-8000-000000000003',digest:'sha256:'+'3'.repeat(64)};c.snapshot.issues.find(i=>i.id==='1000').required_requests.push(extra);c.snapshot.required_repairs[0].references.push(extra);e.issues[0].required_requests.push(extra);c.snapshot.completion_receipts[0]=JSON.stringify(e);assert.equal(validateReceiptChain(JSON.stringify(e)).valid,false);const r=run(c);assert.equal(r.valid,true);assert.deepEqual(selected(r),[]);assert.ok(codes(r).includes('REPAIR_POLICY_PENDING'));
